function sheetSettings(sheetId, tab, destinationId, mode) {
  if (
    !/^[A-Za-z0-9_-]{6,160}$/.test(sheetId) ||
    /^YOUR_/.test(sheetId) ||
    typeof tab !== "string" ||
    !tab.trim() ||
    tab.length > 100
  ) {
    throw new Error("Configure a spreadsheet ID and tab name.");
  }
  if (
    mode === "manual"
      ? !/^[A-Za-z0-9_-]{6,160}$/.test(destinationId) || /^YOUR_/.test(destinationId)
      : !/^[\da-f]{8}(?:-[\da-f]{4}){3}-[\da-f]{12}$/i.test(destinationId)
  ) {
    throw new Error("Configure the destination folder or Linear team before running.");
  }
  return { sheetId, tab: "'" + tab.replace(/'/g, "''") + "'", destinationId };
}

const settings = {
  sheetId: "YOUR_SPREADSHEET_ID",
  tab: "Sheet1",
  folder: "YOUR_DRIVE_FOLDER_ID",
  team: "YOUR_LINEAR_TEAM_UUID",
};
const config = sheetSettings(settings.sheetId, settings.tab, settings.folder, "manual");
return { json: { config, time: $json.timestamp } };

function validUrl(input) {
  const match =
    typeof input === "string" &&
    /^https:\/\/((?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,})([/?#][^\s<>"\\]*)?$/i.exec(
      input.trim(),
    );
  if (!match || match[0].length > 1000)
    throw new Error("Use an authorized public HTTPS webpage URL.");
  const suffix = match[2] ?? "/";
  return "https://" + match[1].toLowerCase() + (suffix.startsWith("/") ? suffix : "/" + suffix);
}

function tablePages(values, compare) {
  if (
    !Array.isArray(values) ||
    JSON.stringify(values[0]?.slice(0, 3)) !== '["service","url","base"]'
  ) {
    throw new Error("Use the sheet columns service, url, base in A1:C1.");
  }
  const pages = [];
  const known = new Set();
  for (const [index, cells] of values.slice(1).entries()) {
    if (!Array.isArray(cells)) throw new Error("Invalid sheet values.");
    if (cells.every((cell) => cell === "" || cell == null)) continue;
    const url = validUrl(cells[1]);
    const fileId = cells[2] ?? "";
    if (known.has(url)) throw new Error("Each tracked URL must have a unique row.");
    if (typeof fileId !== "string" || (fileId !== "" && !/^[a-zA-Z0-9_-]{6,160}$/.test(fileId))) {
      throw new Error("Invalid Drive baseline file ID.");
    }
    if (compare && !fileId)
      throw new Error("Refresh the missing baseline before running comparisons.");
    known.add(url);
    pages.push({
      row: index + 2,
      url,
      fileId,
      key: "apify-screenshot-url:png:1280x1080:full:domcontentloaded:" + url,
    });
  }
  if (pages.length > 12) throw new Error("Use at most twelve tracked pages per workflow.");
  return pages;
}

const response = $input.first().json;
if (response.statusCode !== 200) throw new Error("Could not read the spreadsheet.");
return tablePages(response.body.values, false).map((page) => ({
  json: page,
  pairedItem: { item: 0 },
}));

function actorInput(url) {
  return {
    urls: [{ url }],
    format: "png",
    viewportWidth: 1280,
    delay: 0,
    waitUntil: "domcontentloaded",
    scrollToBottom: false,
    waitUntilNetworkIdleAfterScroll: false,
