}

function baselineName(hex) {
  if (typeof hex !== "string" || !/^[0-9a-f]{64}$/.test(hex))
    throw new Error("Missing page fingerprint.");
  return "visual-baseline-" + hex + ".png";
}

return { json: { page: $json, name: baselineName($json.hash), request: actorInput($json.url) } };

