function screenshotRecord(reply, status, expectedUrl) {
  if (status < 200 || status >= 300 || !Array.isArray(reply) || reply.length !== 1) {
    throw new Error("Apify did not return one result for the webpage.");
  }
  const record = reply[0];
  if (validUrl(record?.startUrl) !== expectedUrl || validUrl(record?.url) !== expectedUrl) {
    throw new Error("Apify returned a different or redirected webpage. Track its final HTTPS URL.");
  }
  const match =
    typeof record.screenshotUrl === "string" &&
    /^https:\/\/api\.apify\.com\/v2\/key-value-stores\/[A-Za-z0-9]+\/records\/([A-Za-z0-9_%-]+)\?[^\s#"<>\\]+$/.exec(
      record.screenshotUrl,
    );
  const query = match && record.screenshotUrl.split("?")[1].split("&");
  if (
    !match ||
    decodeURIComponent(match[1]) !== record.screenshotKey ||
    !query.includes("disableRedirect=true")
  ) {
    throw new Error("Apify did not return the matching signed PNG address.");
  }
  return record.screenshotUrl;
}

