return { json: { url: screenshotRecord($json.body, $json.statusCode, source.page.url) } };

function pngImage(bytes, mime) {
  if (
    !bytes ||
    bytes.length < 57 ||
    bytes.length > 2 * 1024 * 1024 ||
    mime?.split(";")[0].toLowerCase() !== "image/png"
  ) {
    throw new Error("Expected a PNG up to 2 MiB for both screenshots.");
  }
  const png = [137, 80, 78, 71, 13, 10, 26, 10];
  if (!png.every((byte, i) => bytes[i] === byte))
    throw new Error("Screenshot PNG signature is invalid.");
  const readInt = (i) =>
    bytes[i] * 2 ** 24 + bytes[i + 1] * 2 ** 16 + bytes[i + 2] * 2 ** 8 + bytes[i + 3];
  const tag = (i) => String.fromCharCode(...bytes.subarray(i, i + 4));
  const width = readInt(16),
    height = readInt(20);
  if (readInt(8) !== 13 || tag(12) !== "IHDR" || width !== 1280 || height < 1 || height > 16384) {
    throw new Error("Expected a full-page PNG with width 1280 and height up to 16384 pixels.");
  }
  let imageData = false;
  for (let offset = 33; offset + 12 <= bytes.length;) {
    const length = readInt(offset),
      type = tag(offset + 4);
    const next = offset + 12 + length;
    if (next > bytes.length || type === "acTL") break;
    if (type === "IDAT" && length > 0) imageData = true;
    if (type === "IEND" && length === 0 && next === bytes.length && imageData)
      return { width, height };
    offset = next;
  }
  throw new Error("Screenshot PNG is incomplete or animated.");
}

