      !/^[A-Za-z0-9_-]{6,160}$/.test(saved.fileId)
    ) {
      throw new Error("No confirmed baseline for one of the original rows.");
    }
    return { range: tab + "!C" + page.row, majorDimension: "ROWS", values: [[saved.fileId]] };
